// Package instructions writes the non-secret hand-off files used by a
// management operator or an AI assistant to connect to a target machine.
//
// The files generated by this package deliberately contain routing and
// lifecycle metadata only.  In particular, a temporary password, pairing
// code, private key, or access token is never accepted as an input and is
// never written to disk.
package instructions

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"net"
	"os"
	"path"
	"path/filepath"
	"regexp"
	"strings"
	"time"
)

const (
	// SchemaVersion is the version of remote-bridge-connection.json emitted by
	// this package.  Consumers should reject versions they do not understand.
	SchemaVersion = 1

	MarkdownFileName = "REMOTE-BRIDGE.md"
	JSONFileName     = "remote-bridge-connection.json"

	defaultTargetBinary = ".\\bridge-target.exe"
	defaultCLIPath      = ".\\bridge-cli.exe"
)

var (
	planIDPattern = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$`)
	userPattern   = regexp.MustCompile(`^[A-Za-z0-9._@\\-]{1,256}$`)
)

// Request contains the public data needed to create an AI/operator hand-off.
//
// OutputDir must be selected by the caller.  Keeping directory selection out
// of this package avoids accidentally writing instructions into the current
// working directory when a portable executable is launched from a USB drive.
// TargetBinary and CLIPath are optional and default to the portable Windows
// executable names.  ExpiresAt is required so that a generated document does
// not look like a permanent credential.
//
// No field in Request is a password, pairing code, private key, or token.  Do
// not add secret fields to this structure; pass those values out-of-band to
// the secure connection prompt instead.
type Request struct {
	OutputDir string

	PlanID   string
	Hostname string
	Address  string
	// Addresses contains the other local addresses shown to the operator.  The
	// selected Address is always placed first in the generated document.
	Addresses []string

	Port      int
	Transport string
	Username  string

	StatePath    string
	TargetBinary string
	CLIPath      string
	// RevokeCommand optionally overrides the generated target revoke command.
	// It is retained for callers that already render a localized command; the
	// value must still be non-secret text.  When empty, Export derives a command
	// from TargetBinary and StatePath.
	RevokeCommand string

	ExpiresAt time.Time
}

// Document is the machine-readable, non-secret hand-off document.  It is
// intentionally separate from Request so defaults and derived commands are
// visible to callers and tests before the files are written.
type Document struct {
	Version     int       `json:"version"`
	GeneratedAt time.Time `json:"generated_at"`

	PlanID    string   `json:"plan_id"`
	Hostname  string   `json:"target_hostname,omitempty"`
	Address   string   `json:"target_address"`
	Addresses []string `json:"target_addresses,omitempty"`

	Port      int    `json:"port"`
	Transport string `json:"transport"`
	Username  string `json:"username"`

	ExpiresAt *time.Time `json:"expires_at"`
	StatePath string     `json:"state_path"`

	TargetBinary   string `json:"target_binary"`
	CLIPath        string `json:"cli_path"`
	TrustCommand   string `json:"trust_command"`
	ConnectCommand string `json:"connect_command"`
	RevokeCommand  string `json:"revoke_command"`
}

// Result describes the files written by Export.  Document is returned so a
// caller can display the same metadata without reparsing the JSON file.
type Result struct {
	MarkdownPath string
	JSONPath     string
	Document     Document
}

// Export validates req, creates the output directory when needed, and writes
// REMOTE-BRIDGE.md plus remote-bridge-connection.json.  Each file is first
// written to a random temporary file in the destination directory and then
// renamed into place, preventing readers from seeing a partially written
// document.  Existing regular files may be replaced by the platform rename
// operation; unrelated directories and special files are never removed.
func Export(req Request) (Result, error) {
	req.OutputDir = strings.TrimSpace(req.OutputDir)
	doc, err := buildDocument(req, time.Now().UTC())
	if err != nil {
		return Result{}, err
	}
	if err := os.MkdirAll(req.OutputDir, 0o700); err != nil {
		return Result{}, fmt.Errorf("create instructions directory: %w", err)
	}
	info, err := os.Stat(req.OutputDir)
	if err != nil {
		return Result{}, fmt.Errorf("stat instructions directory: %w", err)
	}
	if !info.IsDir() {
		return Result{}, fmt.Errorf("instructions output path is not a directory: %s", req.OutputDir)
	}

	jsonBytes, err := marshalDocument(doc)
	if err != nil {
		return Result{}, err
	}
	markdown := renderMarkdown(doc)

	jsonPath := filepath.Join(req.OutputDir, JSONFileName)
	markdownPath := filepath.Join(req.OutputDir, MarkdownFileName)
	if err := writeAtomic(jsonPath, jsonBytes, 0o600); err != nil {
		return Result{}, fmt.Errorf("write %s: %w", JSONFileName, err)
	}
	if err := writeAtomic(markdownPath, []byte(markdown), 0o600); err != nil {
		return Result{}, fmt.Errorf("write %s: %w", MarkdownFileName, err)
	}
	return Result{MarkdownPath: markdownPath, JSONPath: jsonPath, Document: doc}, nil
}

func buildDocument(req Request, generatedAt time.Time) (Document, error) {
	if strings.TrimSpace(req.OutputDir) == "" {
		return Document{}, errors.New("instructions output directory is required")
	}
	planID := strings.TrimSpace(req.PlanID)
	if !planIDPattern.MatchString(planID) {
		return Document{}, errors.New("plan id must contain 1-128 letters, digits, '.', '_' or '-' characters")
	}
	hostname, err := validateText("hostname", req.Hostname, 253, false)
	if err != nil {
		return Document{}, err
	}
	address := strings.TrimSpace(req.Address)
	if address == "" && len(req.Addresses) > 0 {
		address = strings.TrimSpace(req.Addresses[0])
	}
	if err := validateAddress(address); err != nil {
		return Document{}, err
	}
	addresses := make([]string, 0, len(req.Addresses)+1)
	appendAddress := func(value string) error {
		value = strings.TrimSpace(value)
		if err := validateAddress(value); err != nil {
			return err
		}
		for _, existing := range addresses {
			if strings.EqualFold(existing, value) {
				return nil
			}
		}
		addresses = append(addresses, value)
		return nil
	}
	if err := appendAddress(address); err != nil {
		return Document{}, err
	}
	for _, candidate := range req.Addresses {
		if err := appendAddress(candidate); err != nil {
			return Document{}, err
		}
	}
	if len(addresses) == 0 {
		return Document{}, errors.New("target address is required")
	}

	if req.Port < 1 || req.Port > 65535 {
		return Document{}, errors.New("port must be between 1 and 65535")
	}
	transport, err := validateTransport(req.Transport)
	if err != nil {
		return Document{}, err
	}
	username, err := validateText("username", req.Username, 256, true)
	if err != nil {
		return Document{}, err
	}
	if !userPattern.MatchString(username) {
		return Document{}, errors.New("username contains unsupported characters")
	}
	statePath, err := validateText("state path", req.StatePath, 4096, true)
	if err != nil {
		return Document{}, err
	}
	if statePath == "" {
		return Document{}, errors.New("state path is required")
	}
	targetBinary, err := executablePath(req.TargetBinary, defaultTargetBinary)
	if err != nil {
		return Document{}, fmt.Errorf("target binary: %w", err)
	}
	cliPath, err := executablePath(req.CLIPath, defaultCLIPath)
	if err != nil {
		return Document{}, fmt.Errorf("CLI path: %w", err)
	}
	if req.ExpiresAt.IsZero() {
		return Document{}, errors.New("expiry time is required")
	}
	expires := req.ExpiresAt.UTC()
	generatedAt = generatedAt.UTC()
	if !expires.After(generatedAt) {
		return Document{}, errors.New("expiry time must be after generation time")
	}

	trustCommand := buildTrustCommand(cliPath, address)
	connectCommand := buildConnectCommand(cliPath, address, req.Port, username)
	revokeCommand := buildRevokeCommand(targetBinary, statePath)
	if strings.TrimSpace(req.RevokeCommand) != "" {
		candidate, err := validateCommand(req.RevokeCommand)
		if err != nil {
			return Document{}, fmt.Errorf("revoke command: %w", err)
		}
		revokeCommand = candidate
	}
	return Document{
		Version:        SchemaVersion,
		GeneratedAt:    generatedAt,
		PlanID:         planID,
		Hostname:       hostname,
		Address:        address,
		Addresses:      addresses,
		Port:           req.Port,
		Transport:      transport,
		Username:       username,
		ExpiresAt:      &expires,
		StatePath:      statePath,
		TargetBinary:   targetBinary,
		CLIPath:        cliPath,
		TrustCommand:   trustCommand,
		ConnectCommand: connectCommand,
		RevokeCommand:  revokeCommand,
	}, nil
}

func marshalDocument(doc Document) ([]byte, error) {
	data, err := json.MarshalIndent(doc, "", "  ")
	if err != nil {
		return nil, fmt.Errorf("marshal connection metadata: %w", err)
	}
	data = append(data, '\n')
	return data, nil
}

func validateText(name, value string, max int, required bool) (string, error) {
	value = strings.TrimSpace(value)
	if required && value == "" {
		return "", fmt.Errorf("%s is required", name)
	}
	if len(value) > max {
		return "", fmt.Errorf("%s is too long", name)
	}
	if strings.IndexByte(value, 0) >= 0 {
		return "", fmt.Errorf("%s contains NUL", name)
	}
	for _, r := range value {
		if r == '\r' || r == '\n' || r == '\t' || r < 0x20 || r == 0x7f {
			return "", fmt.Errorf("%s contains control characters", name)
		}
	}
	return value, nil
}

func validateAddress(value string) error {
	if value == "" {
		return errors.New("target address is required")
	}
	if _, err := validateText("target address", value, 253, true); err != nil {
		return err
	}
	if net.ParseIP(value) != nil {
		return nil
	}
	// Hostnames are allowed for management-side name resolution.  Reject path,
	// quoting, and wildcard characters so the derived PowerShell command stays
	// an endpoint argument rather than becoming command syntax.
	if strings.ContainsAny(value, `/\\'"[]*?$`) {
		return errors.New("target address contains unsupported hostname characters")
	}
	if strings.HasPrefix(value, ".") || strings.HasSuffix(value, ".") {
		return errors.New("target address has an invalid hostname")
	}
	for _, part := range strings.Split(value, ".") {
		if part == "" || len(part) > 63 || strings.HasPrefix(part, "-") || strings.HasSuffix(part, "-") {
			return errors.New("target address has an invalid hostname")
		}
		for _, r := range part {
			if !((r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '-') {
				return errors.New("target address has an invalid hostname")
			}
		}
	}
	return nil
}

func validateTransport(value string) (string, error) {
	value = strings.ToLower(strings.TrimSpace(value))
	if value == "" {
		return "", errors.New("transport is required")
	}
	switch value {
	case "http", "https", "winrm-http", "winrm-https":
		return value, nil
	default:
		return "", fmt.Errorf("unsupported transport %q", value)
	}
}

func executablePath(value, fallback string) (string, error) {
	value = strings.TrimSpace(value)
	if value == "" {
		return fallback, nil
	}
	if _, err := validateText("executable path", value, 4096, true); err != nil {
		return "", err
	}
	// A portable package is commonly launched from a removable drive.  An
	// absolute drive letter captured on the target (for example E:\\) is not
	// stable when the same drive is opened on the management machine.  Keep the
	// executable's basename in generated commands instead; the instructions
	// explicitly assume the two bridge executables are in the working folder.
	return portableExecutableBase(value), nil
}

func portableExecutableBase(value string) string {
	value = strings.TrimRight(strings.ReplaceAll(value, "\\", "/"), "/")
	base := path.Base(value)
	if base == "." || base == "/" || base == "" {
		return value
	}
	// PowerShell does not search the current directory for executables by
	// default.  The hand-off directory contains both portable binaries, so
	// make the relative invocation explicit and independent of the USB drive
	// letter assigned on the target or management machine.
	return ".\\" + base
}

func validateCommand(value string) (string, error) {
	value, err := validateText("command", value, 8192, true)
	if err != nil {
		return "", err
	}
	lower := strings.ToLower(strings.ReplaceAll(value, "-", "_"))
	for _, marker := range []string{"password", "passwd", "secret", "private_key", "privatekey", "pairing_code", "access_token", "refresh_token", "bearer"} {
		if strings.Contains(lower, marker) {
			return "", errors.New("command appears to contain secret material")
		}
	}
	return value, nil
}

func buildConnectCommand(cliPath, address string, port int, username string) string {
	return fmt.Sprintf("%s exec --target %s --port %d --username %s --command <PowerShell命令>",
		quotePowerShell(cliPath), quotePowerShell(address), port, quotePowerShell(username))
}

func buildTrustCommand(cliPath, address string) string {
	return fmt.Sprintf("%s trust %s", quotePowerShell(cliPath), quotePowerShell(address))
}

func buildRevokeCommand(targetBinary, statePath string) string {
	return fmt.Sprintf("%s revoke --state %s", quotePowerShell(targetBinary), quotePowerShell(statePath))
}

func quotePowerShell(value string) string {
	return "'" + strings.ReplaceAll(value, "'", "''") + "'"
}

func renderMarkdown(doc Document) string {
	var b strings.Builder
	b.WriteString("# Remote Bridge 连接说明\n\n")
	b.WriteString("此文件由目标机启动程序生成，供管理端操作员或 Codex/其他 AI 读取。它只包含连接元数据，不包含密码、配对码、私钥或访问令牌。\n\n")
	b.WriteString("## 连接信息\n\n")
	fmt.Fprintf(&b, "- 目标机：`%s`\n", markdownValue(doc.Hostname, "未提供"))
	fmt.Fprintf(&b, "- 目标地址：`%s`\n", markdownValue(doc.Address, "未提供"))
	if len(doc.Addresses) > 1 {
		b.WriteString("- 目标机其他地址：")
		for i, address := range doc.Addresses[1:] {
			if i > 0 {
				b.WriteString(", ")
			}
			fmt.Fprintf(&b, "`%s`", address)
		}
		b.WriteByte('\n')
	}
	fmt.Fprintf(&b, "- 传输：`%s`\n", doc.Transport)
	fmt.Fprintf(&b, "- 端口：`%d`\n", doc.Port)
	fmt.Fprintf(&b, "- 临时账号：`%s`\n", doc.Username)
	b.WriteString("- 账号说明：默认账号名固定为 `RemoteBridge`；每次 apply 会重新生成随机密码，密码只在目标机窗口显示一次。\n")
	fmt.Fprintf(&b, "- 计划 ID：`%s`\n", doc.PlanID)
	if doc.ExpiresAt != nil {
		fmt.Fprintf(&b, "- 过期时间（UTC）：`%s`\n", doc.ExpiresAt.Format(time.RFC3339))
	}
	b.WriteString("\n## 给 Codex/AI 的操作规则\n\n")
	b.WriteString("1. 使用下面的 `bridge-cli` 命令连接目标机；执行时会在控制台安全提示输入临时密码。\n")
	b.WriteString("2. 不要把密码、配对码、命令输出或私钥写入本目录、说明文件、命令参数或审计日志。\n")
	b.WriteString("3. 只在用户明确授权的目标机上执行命令，并在会话结束后撤销临时入口。\n")
	b.WriteString("4. 连接前检查过期时间；过期后不要继续尝试，应让用户重新配置。\n\n")
	fmt.Fprintf(&b, "如果目标地址尚未确认，可先在管理机运行 `%s discover --once --json`（目标机交互窗口仍需保持打开）；发现公告只用于定位，不包含密码，也不能替代人工确认。\n\n", quotePowerShell(doc.CLIPath))
	b.WriteString("首次使用 IP 连接时，先在管理机运行下面的 TrustedHosts 配置命令；如果当前不是管理员，`bridge-cli` 会自动唤起标准 Windows UAC，用户点击“是”后继续：\n\n```powershell\n")
	b.WriteString(doc.TrustCommand)
	b.WriteString("\n```\n\n该命令只对当前目标地址添加信任；UAC 仍需要用户明确确认，`exec`/`shell` 不会自动提升权限。\n\n")
	b.WriteString("连接示例（将 `<PowerShell命令>` 替换为用户明确要求的命令）：\n\n")
	b.WriteString("```powershell\n")
	b.WriteString(doc.ConnectCommand)
	b.WriteString("\n```\n\n")
	b.WriteString("撤销临时入口（回到目标机的管理员 PowerShell 执行）：\n\n```powershell\n")
	b.WriteString(doc.RevokeCommand)
	b.WriteString("\n```\n\n")
	b.WriteString("机器可读信息：`remote-bridge-connection.json`。状态文件路径仅用于撤销，不应复制或上传到不受信任的位置。\n")
	return b.String()
}

func markdownValue(value, fallback string) string {
	if value == "" {
		return fallback
	}
	return value
}

func writeAtomic(path string, data []byte, mode os.FileMode) error {
	dir := filepath.Dir(path)
	base := filepath.Base(path)
	var random [8]byte
	if _, err := rand.Read(random[:]); err != nil {
		return fmt.Errorf("generate temporary filename: %w", err)
	}
	tmp := filepath.Join(dir, "."+base+".tmp-"+hex.EncodeToString(random[:]))
	f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, mode)
	if err != nil {
		return err
	}
	removeTemp := true
	defer func() {
		if removeTemp {
			_ = os.Remove(tmp)
		}
	}()
	if err := f.Chmod(mode); err != nil {
		_ = f.Close()
		return err
	}
	if _, err := f.Write(data); err != nil {
		_ = f.Close()
		return err
	}
	if err := f.Sync(); err != nil {
		_ = f.Close()
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}
	if err := os.Rename(tmp, path); err != nil {
		return err
	}
	removeTemp = false
	return nil
}
